Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Car Race – Three.js</title>
  <style>
    body { margin: 0; overflow: hidden; background: #000; }
    #info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      font-family: 'Segoe UI', sans-serif;
      font-size: 18px;
      background: rgba(0,0,0,0.6);
      padding: 8px 16px;
      border-radius: 8px;
      pointer-events: none;
      user-select: none;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="info">🏁 Red overtakes Blue – Race loops forever</div>
  <script type="importmap">
    {
      "imports": {
        "three": "./three.module.js"
      }
    }
  </script>
  <script type="module">
    import * as THREE from 'three';

    // --- Setup Scene, Camera, Renderer ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 200);
    camera.position.set(12, 8, 18);
    camera.lookAt(0, 0, 5);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // --- Lights ---
    const ambientLight = new THREE.AmbientLight(0x404060);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
    dirLight.position.set(10, 20, 10);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    const d = 30;
    dirLight.shadow.camera.left = -d;
    dirLight.shadow.camera.right = d;
    dirLight.shadow.camera.top = d;
    dirLight.shadow.camera.bottom = -d;
    dirLight.shadow.camera.near = 1;
    dirLight.shadow.camera.far = 50;
    scene.add(dirLight);

    const fillLight = new THREE.PointLight(0x4466ff, 0.3);
    fillLight.position.set(-5, 5, 10);
    scene.add(fillLight);

    // --- Ground ---
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a3f47, roughness: 0.8 });
    const groundGeo = new THREE.PlaneGeometry(40, 20);
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.3;
    ground.receiveShadow = true;
    scene.add(ground);

    // --- Track markings (simple dashed lines) ---
    const trackMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.6 });
    for (let i = -10; i <= 10; i += 2) {
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.05, 0.8), trackMat);
      stripe.position.set(i, 0.01, 5);
      stripe.rotation.x = -Math.PI / 2;
      scene.add(stripe);
    }

    // --- Finish line (checkerboard style) ---
    const finishGroup = new THREE.Group();
    const whiteMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3 });
    const blackMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.3 });
    for (let y = -0.5; y <= 0.5; y += 0.25) {
      for (let x = -0.5; x <= 0.5; x += 0.25) {
        const isWhite = ((Math.round(x * 4) + Math.round(y * 4)) % 2 === 0);
        const tile = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.05, 0.22), isWhite ? whiteMat : blackMat);
        tile.position.set(x, 0.05, y);
        finishGroup.add(tile);
      }
    }
    // upright poles
    const poleMat = new THREE.MeshStandardMaterial({ color: 0xffaa00, emissive: 0x441100 });
    for (let side = -1; side <= 1; side += 2) {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.8), poleMat);
      pole.position.set(side * 0.6, 0.4, 0);
      finishGroup.add(pole);
    }
    finishGroup.position.set(0, 0.05, 8);
    scene.add(finishGroup);

    // --- Helper: Car builder ---
    function createCar(color, isRed) {
      const group = new THREE.Group();

      // body (main box)
      const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.4, metalness: 0.3 });
      const body = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.3, 0.6), bodyMat);
      body.position.y = 0.15;
      body.castShadow = true;
      body.receiveShadow = true;
      group.add(body);

      // cabin (top)
      const cabinMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.5, metalness: 0.2 });
      const cabin = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.25, 0.55), cabinMat);
      cabin.position.set(0, 0.35, 0);
      cabin.castShadow = true;
      cabin.receiveShadow = true;
      group.add(cabin);

      // windscreen (glass)
      const glassMat = new THREE.MeshStandardMaterial({ color: 0x88ccff, roughness: 0.1, metalness: 0.1, transparent: true, opacity: 0.6 });
      const glass = new THREE.Mesh(new THREE.BoxGeometry(0.45, 0.18, 0.02), glassMat);
      glass.position.set(0, 0.28, 0.28);
      group.add(glass);

      // wheels
      const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.9 });
      const wheelPositions = [[-0.35, 0.05, 0.35], [-0.35, 0.05, -0.35], [0.35, 0.05, 0.35], [0.35, 0.05, -0.35]];
      for (const pos of wheelPositions) {
        const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.08), wheelMat);
        wheel.rotation.x = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        wheel.castShadow = true;
        wheel.receiveShadow = true;
        group.add(wheel);
      }

      // spoiler (red car only)
      if (isRed) {
        const spoilerMat = new THREE.MeshStandardMaterial({ color: 0xcc2200, roughness: 0.5 });
        const spoiler = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.04, 0.15), spoilerMat);
        spoiler.position.set(0, 0.35, -0.35);
        group.add(spoiler);
        // extra stripe
        const stripeMat = new THREE.MeshStandardMaterial({ color: 0xffaa00, emissive: 0x442200 });
        const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.02, 0.02), stripeMat);
        stripe.position.set(0, 0.18, 0.28);
        group.add(stripe);
      } else {
        // blue car: small antenna
        const antMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa });
        const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.01, 0.01, 0.15), antMat);
        ant.position.set(0, 0.45, 0.15);
        group.add(ant);
      }

      // headlights
      const lightMat = new THREE.MeshStandardMaterial({ color: 0xffeedd, emissive: 0x664422 });
      for (let side = -0.3; side <= 0.3; side += 0.6) {
        const hl = new THREE.Mesh(new THREE.SphereGeometry(0.06), lightMat);
        hl.position.set(side, 0.1, 0.35);
        group.add(hl);
      }

      return group;
    }

    // --- Create Cars ---
    const redCar = createCar(0xff3300, true);
    redCar.position.set(-2, 0.15, -2); // start left lane
    scene.add(redCar);

    const blueCar = createCar(0x2266ff, false);
    blueCar.position.set(2, 0.15, -2); // start right lane
    scene.add(blueCar);

    // --- Race state ---
    const finishZ = 8;
    const startZ = -2;
    const totalDistance = finishZ - startZ; // 10 units

    let time = 0;
    let raceDone = false;
    let resetTimer = 0;

    // --- Animation loop ---
    function animate() {
      const delta = 0.016; // ~60fps, consistent step
      time += delta;

      // Blue car: fast start, then constant speed (slower later)
      // Red car: slower start, then accelerates, overtakes mid-race

      // Use parametric functions: progress from 0 to 1 over ~6 seconds
      // Blue: ease out (fast early, then plateaus)
      // Red: ease in (slow early, then catches up)

      const raceDuration = 5.8; // seconds for full race
      const t = Math.min(time / raceDuration, 1); // 0..1

      // Blue progress: cubic ease-out (fast start, slow end)
      const blueProgress = 1 - Math.pow(1 - t, 2.5);
      // Red progress: cubic ease-in (slow start, fast catch-up)
      const redProgress = t < 0.5 ? 0.5 * Math.pow(2 * t, 2) : 1 - 0.5 * Math.pow(2 - 2 * t, 2); // smoothstep
      // Actually use a custom: red accelerates later: 
      const redCurve = t < 0.3 ? 0.3 * (t/0.3)**1.8 : 0.3 + 0.7 * ((t-0.3)/0.7)**1.2;
      // Simpler: red catches up at ~0.55
      let redT = t;
      if (t < 0.45) redT = t * 1.2; // slower start
      else redT = t * 1.0 + 0.05; // then faster
      const redProgress2 = Math.min(redT, 1);

      // Use a more reliable overtake: red wins at t ~0.75
      // Blue: linear-ish but early lead
      const blueZ = startZ + totalDistance * Math.min(t * 1.1, 1); // blue caps at finish
      // Red: slower start, then catches up, passes at ~0.7
      let redRaw = t < 0.3 ? t * 0.6 : 0.18 + (t - 0.3) * 1.5;
      redRaw = Math.min(redRaw, 1);
      const redZ = startZ + totalDistance * redRaw;

      // Ensure red overtakes and wins
      // Actually let's define positions directly:
      // Blue: 0..1 but saturates at 1
      const blueT = Math.min(t * 1.0, 1);
      const bluePos = startZ + totalDistance * blueT;

      // Red: slower until t=0.35, then faster, overtakes at t~0.6
      let redT2 = t;
      if (t < 0.35) redT2 = t * 0.5;
      else redT2 = 0.175 + (t - 0.35) * 1.25;
      redT2 = Math.min(redT2, 1);
      const redPos = startZ + totalDistance * redT2;

      // Update positions
      redCar.position.z = redPos;
      blueCar.position.z = bluePos;

      // Slight y wobble for visual
      redCar.position.y = 0.15 + 0.03 * Math.sin(time * 8 + 1.2);
      blueCar.position.y = 0.15 + 0.03 * Math.sin(time * 8 + 0.7);

      // Check finish: red crosses first -> reset after short delay
      if (redPos >= finishZ && !raceDone) {
        raceDone = true;
        resetTimer = time;
      }

      // If race finished and red won, reset after 1.5s
      if (raceDone && (time - resetTimer) > 1.8) {
        // reset positions
        redCar.position.z = startZ;
        blueCar.position.z = startZ;
        time = 0;
        raceDone = false;
        // small random offset for variety
        redCar.position.x = -2 + 0.1 * (Math.random() - 0.5);
        blueCar.position.x = 2 + 0.1 * (Math.random() - 0.5);
      }

      // Camera follows action
      const midZ = (redPos + bluePos) / 2;
      const camZ = Math.max(midZ + 4, 6);
      camera.position.z = camZ;
      camera.position.x = 0;
      camera.position.y = 8 + 0.2 * Math.sin(time * 0.5);
      camera.lookAt(0, 0.5, midZ);

      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    // --- Resize handler ---
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // --- Extra: small floating label (CSS) ---
    const style = document.createElement('style');
    style.textContent = `
      #info {
        background: rgba(0,20,40,0.8);
        border: 2px solid #ffaa33;
        box-shadow: 0 0 20px #ff6600;
      }
    `;
    document.head.appendChild(style);
  </script>
</body>
</html>
```
